#!/usr/bin/env node
/**
 * Pre-commit: enforce migration file boundaries.
 *
 * Rules (from AGENTS.md):
 *   1. Autogenerated migration files (contain "# ### commands auto generated by Alembic")
 *      MUST NOT contain op.execute() calls. Pure DDL only.
 *   2. Hand-written data migration files (no autogenerate marker)
 *      MUST contain "# Manual override reason: data_only" in the module docstring.
 *   3. Violations are rejected with self-contained fix instructions.
 */
const { execSync } = require("node:child_process");
const { readFileSync } = require("node:fs");
const path = require("node:path");

const ROOT = execSync("git rev-parse --show-toplevel", { encoding: "utf-8" }).trim();
const MIG_DIR = path.join(ROOT, "backend", "migrations", "versions");

const staged = execSync(
  `git diff --cached --name-only --diff-filter=ACM -- "${MIG_DIR}/*.py"`,
  { encoding: "utf-8" },
).trim();

if (!staged) process.exit(0);

const files = staged.split("\n").filter(Boolean);
const AUTOGEN_MARKER = "# ### commands auto generated by Alembic";
const REASON_PREFIX = "# Manual override reason:";
const VALID_REASONS = ["data_only"];

let errors = 0;

for (const f of files) {
  const basename = path.basename(f);
  const rel = path.relative(ROOT, f);
  const content = readFileSync(f, "utf-8");
  const hasAutogen = content.includes(AUTOGEN_MARKER);

  if (hasAutogen) {
    // Rule 1: autogenerated files must be pure DDL — no op.execute()
    if (/^\s+op\.execute\(/m.test(content)) {
      errors++;
      console.error([
        ``,
        `  ================================================================`,
        `  MIGRATION CHECK FAILED`,
        `  ================================================================`,
        `  File:  ${basename}`,
        `  Error: Autogenerated migration contains op.execute()`,
        `  Rule:  AGENTS.md — DDL migrations must NOT contain data ops.`,
        `         Create a separate data_only migration.`,
        `  ----------------------------------------------------------------`,
        `  Fix:`,
        `    1. Remove all op.execute() lines from this file`,
        `    2. Run:  pnpm run db:data "your_description"`,
        `    3. Move the op.execute() logic into the new file`,
        `    4. Run:  pnpm run db:migrate`,
        `  ================================================================`,
        ``,
      ].join("\n"));
    }
  } else {
    // Rule 2: hand-written files must declare data_only reason
    const reasonLine = content
      .split("\n")
      .find((l) => l.trimStart().startsWith(REASON_PREFIX));
    const reason = reasonLine?.split(":")[1]?.trim();

    if (!reason || !VALID_REASONS.includes(reason)) {
      errors++;
      console.error([
        ``,
        `  ================================================================`,
        `  MIGRATION CHECK FAILED`,
        `  ================================================================`,
        `  File:  ${basename}`,
        `  Error: Migration is neither autogenerated DDL nor has a valid`,
        `         manual override reason.`,
        `  Rule:  AGENTS.md - Two kinds of migration, never mixed:`,
        `         DDL = autogenerated, Data = manual with reason marker.`,
        `  ----------------------------------------------------------------`,
        `  If this should be autogenerated DDL:`,
        `    1. Delete this file`,
        `    2. Run:  pnpm run db:migration "description"`,
        ``,
        `  If this is a hand-written data migration:`,
        `    1. Add this to the module docstring:`,
        `         # Manual override reason: data_only`,
        `    2. Ensure down_revision points to the current alembic head`,
        `  ================================================================`,
        ``,
      ].join("\n"));
    }
  }
}

if (errors > 0) {
  console.error(`  ${errors} migration file(s) failed. See AGENTS.md § Migration Rules.\n`);
  process.exit(1);
}
